\begin{figure}[H]\label{fig:dependency-graph}
    \centering
    \begin{tikzpicture}[
            every node/.style = {
                draw, rectangle, 
                minimum height = 1.5em, 
                outer sep = 2.5pt, 
                inner ysep = 0pt
            }
        ]

            \node (a) at (8.8em, 0em) {\small{\cref{cor:infinitely-many-pairs}}};
            \node (b) at (8.8em, 3em) {\small{\cref{thm:main-thm}}};

            \node (c1) at (5.1em, 6em) {\small{\cref{thm:c-greater-than-2}}};
            \node (c2) at (12.5em, 6em) {\small{\cref{prop:fourier-transform}}};

            \node (d1) at (-0.4em, 9em) {\small{\cref{prop:estimate-sigma1}}};
            \node (d2) at (11.1em, 9em) {\small{\cref{prop:estimate-sigma2}}};

            \node (e1) at (-13em, 12em) {\small{\cref{lem:parseval-bound}}};
            \node (e2) at (-6.7em, 12em) {\small{\cref{lem:rational-approx-bound}}};
            \node (e3) at (-0.4em, 12em) {\small{\cref{lem:small-xi-bound}}};
            \node (e4) at (5.9em, 12em) {\small{\cref{lem:poulias-bound}}};

            \node (f1) at (-6.7em, 15em) {\small{\cref{thm:vinogradov}}};
            \node (f2) at (3.5em, 15em) {\small{\cref{thm:poulias}}};
            \node (f3) at (11.1em, 15em) {\small{\cref{prop:estimate-sigma2-details}}};

            \node (g1) at (3.9em, 18em) {\small{\cref{lem:turan-bound}}};
            \node (g2) at (11.1em, 18em) {\small{\cref{cor:bound-for-turan-bound}}};
            \node (g3) at (18.3em, 18em) {\small{\cref{thm:vdc-estimate}}};

            \node (h1) at (-6.2em, 21em) {\small{\cref{lem:partition-bound}}};
            \node (h2) at (0.5em, 21em) {\small{\cref{lem:ft-bounds-for-measures}}};
            \node (h3) at (7.2em, 21em) {\small{\cref{lem:expectation-to-measure}}};
            \node (h4) at (14.1em, 21em) {\small{\cref{thm:erdos-turan}}};

            \node (i) at (3.9em, 24em) {\small{\cref{lem:measure-stuff}}};


            \graph[use existing nodes]{
                i -> {h2, h3};
                {h1, h2, h3, h4} -> g1;
                {g1, g2, g3} -> f3 ->["\small{\cref{lem:sigma2-proof-works}}"{draw = none}] d2;
                f1 -> e2;
                f2 -> e4;
                {e1, e2, e3, e4} -> d1;
                {d1, d2} -> c1;
                {c1, c2} -> b -> a;
            };
    \end{tikzpicture}
    \caption{Dependency graph. An arrow from vertex \(a\) to vertex \(b\) denotes that the proof of \(b\) depends on \(a\).}
\end{figure}

